2623  static SOPC_ReturnStatus SOPC_Variant_Read_Internal(SOPC_Variant* variant, SOPC_Buffer* buf, uint32_t nestedStructLevel)
  2624  {
  2625      SOPC_Byte encodingByte = 0;
  2626      int32_t arrayLength = 0;
  2627      int64_t matrixLength = 1;
  2628
  2629      const SOPC_Common_EncodingConstants* encCfg = SOPC_Internal_Common_GetEncodingConstants();
  2630
  2631      if (NULL == variant)
  2632      {
  2633          return SOPC_STATUS_INVALID_PARAMETERS;
  2634      }
  2635      else if (nestedStructLevel >= encCfg->max_nested_struct)
  2636      {
  2637          return SOPC_STATUS_INVALID_STATE;
  2638      }
  2639
  2640      nestedStructLevel++;
  2641      SOPC_ReturnStatus status = SOPC_Byte_Read(&encodingByte, buf, nestedStructLevel);
  2642
  2643      if (SOPC_STATUS_OK == status)
  2644      {
  2645          // Retrieve array flags
  2646          if ((encodingByte & SOPC_VariantArrayValueFlag) != 0)
  2647          {
  2648              if ((encodingByte & SOPC_VariantArrayDimensionsFlag) != 0)
  2649              {
  2650                  variant->ArrayType = SOPC_VariantArrayType_Matrix;
  2651              }
  2652              else
  2653              {
  2654                  variant->ArrayType = SOPC_VariantArrayType_Array;
  2655              }
  2656              // Note array length read in ReadVariantArrayBuiltInType
  2657          }
  2658          else if ((encodingByte & SOPC_VariantArrayDimensionsFlag) != 0)
  2659          {
  2660              status = SOPC_STATUS_INVALID_PARAMETERS;
  2661          }
  2662          else
  2663          {
  2664              variant->ArrayType = SOPC_VariantArrayType_SingleValue;
  2665          }
  2666          // Retrieve builtin type id: avoid 2^7 and 2^6 which are array flags
  2667          variant->BuiltInTypeId = 0x3F & encodingByte;
  2668      }
  2669
  2670      if (SOPC_STATUS_OK == status)
  2671      {
  2672          switch (variant->ArrayType)
  2673          {
  2674          case SOPC_VariantArrayType_SingleValue:
  2675              status = ReadVariantNonArrayBuiltInType(buf, variant->BuiltInTypeId, &variant->Value, nestedStructLevel);
  2676              break;
  2677          case SOPC_VariantArrayType_Array:
  2678              status = ReadVariantArrayBuiltInType(buf, variant->BuiltInTypeId, &variant->Value.Array.Content,
  2679                                                   &arrayLength, nestedStructLevel);
  2680              variant->Value.Array.Length = arrayLength;
  2681              break;
  2682          case SOPC_VariantArrayType_Matrix:
  2683              status = ReadVariantArrayBuiltInType(buf, variant->BuiltInTypeId, &variant->Value.Matrix.Content,
  2684                                                   &arrayLength, nestedStructLevel);
  2685
  2686              if (SOPC_STATUS_OK == status && arrayLength < 0)
  2687              {
  2688                  status = SOPC_STATUS_ENCODING_ERROR;
  2689              }
  2690
  2691              // Decode dimension array
  2692              if (SOPC_STATUS_OK == status)
  2693              {
  2694                  // length of array
  2695                  status = SOPC_Int32_Read(&variant->Value.Matrix.Dimensions, buf, nestedStructLevel);
  2696              }
  2697
  2698              if (SOPC_STATUS_OK == status &&
  2699                  (variant->Value.Matrix.Dimensions < 0 || variant->Value.Matrix.Dimensions > encCfg->max_array_length ||
  2700                   (uint64_t) variant->Value.Matrix.Dimensions * 1 > SIZE_MAX))
  2701              {
  2702                  status = SOPC_STATUS_OUT_OF_MEMORY;
  2703              }
  2704
  2705              if (SOPC_STATUS_OK == status)
  2706              {
  2707                  // array
  2708                  variant->Value.Matrix.ArrayDimensions =
  2709                      SOPC_Malloc(sizeof(int32_t) * (size_t) variant->Value.Matrix.Dimensions);
  2710                  if (variant->Value.Matrix.Dimensions == 0)
  2711                  {
  2712                      matrixLength = 0;
  2713                  }
  2714                  if (NULL != variant->Value.Matrix.ArrayDimensions)
  2715                  {
  2716                      int32_t idx = 0;
  2717                      for (idx = 0; idx < variant->Value.Matrix.Dimensions && SOPC_STATUS_OK == status; idx++)
  2718                      {
  2719                          status = SOPC_Int32_Read(&variant->Value.Matrix.ArrayDimensions[idx], buf, nestedStructLevel);
  2720                          if (SOPC_STATUS_OK == status && variant->Value.Matrix.ArrayDimensions[idx] > 0)
  2721                          {
  2722                              // valid value
  2723                              matrixLength *= variant->Value.Matrix.ArrayDimensions[idx];
  2724                              if (matrixLength > arrayLength)
  2725                              {
  2725                              {
  2726                                  status = SOPC_STATUS_ENCODING_ERROR;
  2727                              }
  2728                          }
  2729                          else
  2730                          {
  2731                              status = SOPC_STATUS_ENCODING_ERROR;
  2732                          }
  2733                      }
  2734                      if (SOPC_STATUS_OK != status)
  2735                      {
  2736                          SOPC_Free(variant->Value.Matrix.ArrayDimensions);
  2737                          variant->Value.Matrix.ArrayDimensions = NULL;
  2738                      }
  2739                  }
  2740                  else
  2741                  {
  2742                      status = SOPC_STATUS_NOK;
  2743                  }
  2744              }
  2745
  2746              if (SOPC_STATUS_OK == status && matrixLength != arrayLength)
  2747              {
  2748                  // Dimensions length and total length are not equal
  2749                  status = SOPC_STATUS_ENCODING_ERROR;
  2750              }
  2751
  2752              if (SOPC_STATUS_OK != status)
  2753              {
  2754                  if (arrayLength > 0)
  2755                  {
  2756                      // manage cases in which Dimensions or ArrayDimensions are not correctly
  2757                      // decoded. Force to use only arrayLength value to ensure correct cleaning
  2758                      // of the matrix content.
  2759                      variant->Value.Matrix.Dimensions = 1;
  2760                      int32_t* arrayDim = SOPC_Calloc(1, sizeof(int32_t));
  2761                      if (NULL != arrayDim)
  2762                      {
  2763                          arrayDim[0] = arrayLength;
  2764                          /* free if memory was previously allocated */
  2765                          if (NULL != variant->Value.Matrix.ArrayDimensions)
  2766                          {
  2767                              SOPC_Free(variant->Value.Matrix.ArrayDimensions);
  2768                          }
  2769                          variant->Value.Matrix.ArrayDimensions = arrayDim;
  2770                      }
  2771                      else
  2772                      {
  2773                          status = SOPC_STATUS_OUT_OF_MEMORY;
  2774                      }
  2775                  }
  2776                  else
  2777                  {
  2778                      variant->Value.Matrix.Dimensions = 0;
  2779                  }
  2780              }
  2781
  2782              if (SOPC_STATUS_OK != status)
  2783              {
  2784                  SOPC_Variant_Clear(variant);
  2785              }
  2786
  2787              break;
  2788          default:
  2789              status = SOPC_STATUS_ENCODING_ERROR;
  2790              break;
  2791          }
  2792      }
  2793
